"""Minimal Open Packaging Conventions reader for .docx files."""
from __future__ import annotations

import io
import os
import posixpath
import zipfile
from dataclasses import dataclass
from xml.etree import ElementTree as ET

RT = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships/'
RT_OFFICE_DOCUMENT = RT + 'officeDocument'
RT_STYLES = RT + 'styles'
RT_NUMBERING = RT + 'numbering'
RT_THEME = RT + 'theme'
RT_SETTINGS = RT + 'settings'
RT_FOOTNOTES = RT + 'footnotes'
RT_ENDNOTES = RT + 'endnotes'
RT_HEADER = RT + 'header'
RT_FOOTER = RT + 'footer'
RT_IMAGE = RT + 'image'
RT_HYPERLINK = RT + 'hyperlink'


@dataclass(frozen=True)
class Relationship:
    id: str
    type: str
    target: str
    external: bool = False


class Package:
    """A read-only view of a .docx zip container."""

    def __init__(self, source):
        if isinstance(source, (bytes, bytearray)):
            self._buf = bytes(source)
            self.path = None
        elif hasattr(source, 'read'):
            self._buf = source.read()
            self.path = getattr(source, 'name', None)
        else:
            self.path = os.fspath(source)
            with open(self.path, 'rb') as fh:
                self._buf = fh.read()
        try:
            self._zip = zipfile.ZipFile(io.BytesIO(self._buf))
        except zipfile.BadZipFile as exc:
            hint = ''
            if self._buf[:8] == b'\xd0\xcf\x11\xe0\xa1\xb1\x1a\xe1':
                hint = (' This looks like a legacy binary .doc file; only the '
                        'Open XML .docx format is supported.')
            raise ValueError('not a valid .docx package: %s.%s' % (exc, hint)) from exc
        self._names = set(self._zip.namelist())
        self._xml_cache: dict[str, ET.Element] = {}
        self._rels_cache: dict[str, dict[str, Relationship]] = {}

    # -- raw access ---------------------------------------------------------
    def __contains__(self, name: str) -> bool:
        return name.lstrip('/') in self._names

    def names(self):
        return sorted(self._names)

    def read(self, name: str) -> bytes:
        return self._zip.read(name.lstrip('/'))

    def xml(self, name: str):
        """Parsed XML root of a part, or ``None`` when the part is missing."""
        name = name.lstrip('/')
        if name in self._xml_cache:
            return self._xml_cache[name]
        if name not in self._names:
            return None
        root = ET.fromstring(self._zip.read(name))
        self._xml_cache[name] = root
        return root

    # -- relationships ------------------------------------------------------
    @staticmethod
    def rels_name(part_name: str) -> str:
        directory, base = posixpath.split(part_name.lstrip('/'))
        return posixpath.join(directory, '_rels', base + '.rels')

    def rels(self, part_name: str) -> dict[str, Relationship]:
        part_name = part_name.lstrip('/')
        cached = self._rels_cache.get(part_name)
        if cached is not None:
            return cached
        out: dict[str, Relationship] = {}
        root = self.xml(self.rels_name(part_name))
        if root is not None:
            for rel in root:
                rid = rel.get('Id')
                if not rid:
                    continue
                out[rid] = Relationship(
                    id=rid,
                    type=rel.get('Type', ''),
                    target=rel.get('Target', ''),
                    external=(rel.get('TargetMode') == 'External'),
                )
        self._rels_cache[part_name] = out
        return out

    @staticmethod
    def resolve(source_part: str, target: str) -> str:
        if target.startswith('/'):
            return target.lstrip('/')
        base = posixpath.dirname(source_part.lstrip('/'))
        return posixpath.normpath(posixpath.join(base, target))

    def related(self, source_part: str, rid: str):
        """Resolved part name for *rid*; external rels return their URL."""
        rel = self.rels(source_part).get(rid)
        if rel is None:
            return None
        if rel.external:
            return rel.target
        return self.resolve(source_part, rel.target)

    def related_by_type(self, source_part: str, rel_type: str):
        for rel in self.rels(source_part).values():
            if rel.type == rel_type:
                if rel.external:
                    return rel.target
                return self.resolve(source_part, rel.target)
        return None

    # -- well known parts ---------------------------------------------------
    @property
    def main_part(self) -> str:
        name = self.related_by_type('/', RT_OFFICE_DOCUMENT)
        if name is None:
            for candidate in ('word/document.xml', 'word/document2.xml'):
                if candidate in self._names:
                    return candidate
            raise ValueError('package has no main document part')
        return name

    def part_by_type(self, rel_type: str):
        """A part related to the main document, as ``(name, xml_root)``."""
        name = self.related_by_type(self.main_part, rel_type)
        if name is None:
            return None, None
        return name, self.xml(name)

    def image_bytes(self, source_part: str, rid: str):
        name = self.related(source_part, rid)
        if not name or name.startswith(('http://', 'https://', 'file:')):
            return None
        try:
            return self._zip.read(name)
        except KeyError:
            return None

    def replace(self, updates: dict[str, bytes]) -> bytes:
        """New package bytes with the given parts replaced."""
        out = io.BytesIO()
        with zipfile.ZipFile(out, 'w', zipfile.ZIP_DEFLATED) as zout:
            for item in self._zip.infolist():
                data = updates.get(item.filename)
                if data is None:
                    data = self._zip.read(item.filename)
                zout.writestr(item, data)
        return out.getvalue()
